const ldap = require('ldapjs');
const express = require('express');
const multer = require('multer');
const csv = require('csv-parser');
const fs = require('fs');
const path = require('path');
const { Readable } = require('stream');

const app = express();
const upload = multer({ dest: '/tmp/uploads/', limits: { fileSize: 1024 * 1024 } });

const LDAP_URL = process.env.LDAP_URL || 'ldap://localhost:389';
const LDAP_BASE_DN = process.env.LDAP_BASE_DN || 'dc=corp,dc=example,dc=com';
const LDAP_BIND_DN = process.env.LDAP_BIND_DN || 'cn=admin,dc=corp,dc=example,dc=com';
const LDAP_BIND_PW = process.env.LDAP_BIND_PW || 'admin_secret';

class LDAPFieldEncoder {
  constructor(options = {}) {
    this.allowWildcard = options.allowWildcard || false;
    this.maxLength = options.maxLength || 256;
    this.encodingMap = this._buildEncodingMap();
  }

  _buildEncodingMap() {
    const map = new Map();
    map.set('\\', '\\5c');
    map.set('(', '\\28');
    map.set(')', '\\29');
    map.set('\0', '\\00');
    map.set('*', '\\2a');
    return map;
  }

  encode(value) {
    if (typeof value !== 'string') return '';
    if (value.length > this.maxLength) {
      value = value.substring(0, this.maxLength);
    }
    let encoded = value;
    for (const [char, replacement] of this.encodingMap) {
      encoded = encoded.split(char).join(replacement);
    }
    return encoded;
  }
}

class UserLookupService {
  constructor(ldapConfig) {
    this.config = ldapConfig;
    this.encoder = new LDAPFieldEncoder({ allowWildcard: false });
    this.client = null;
  }

  async connect() {
    return new Promise((resolve, reject) => {
      this.client = ldap.createClient({ url: this.config.url });
      this.client.bind(this.config.bindDN, this.config.bindPW, (err) => {
        if (err) reject(err);
        else resolve();
      });
    });
  }

  buildFilter(fieldName, fieldValue) {
    const sanitizedValue = this.encoder.encode(fieldValue);
    const sanitizedField = this._validateFieldName(fieldName);
    return `(${sanitizedField}=${sanitizedValue})`;
  }

  _validateFieldName(name) {
    const allowed = /^[a-zA-Z][a-zA-Z0-9-]*$/;
    if (!allowed.test(name)) {
      throw new Error(`Invalid LDAP attribute name: ${name}`);
    }
    return name;
  }

  async searchUser(filter) {
    return new Promise((resolve, reject) => {
      const opts = {
        filter: filter,
        scope: 'sub',
        attributes: ['dn', 'cn', 'mail', 'uid', 'memberOf']
      };
      const results = [];
      this.client.search(this.config.baseDN, opts, (err, res) => {
        if (err) return reject(err);
        res.on('searchEntry', (entry) => results.push(entry.object));
        res.on('error', (err) => reject(err));
        res.on('end', () => resolve(results));
      });
    });
  }

  disconnect() {
    if (this.client) this.client.unbind();
  }
}

class BatchProcessor {
  constructor(lookupService) {
    this.service = lookupService;
    this.fieldMapping = {
      'email': 'mail',
      'username': 'uid',
      'name': 'cn',
      'employee_id': 'employeeNumber'
    };
  }

  normalizeRecord(record) {
    const normalized = {};
    for (const [key, value] of Object.entries(record)) {
      const trimmedKey = key.trim().toLowerCase();
      const trimmedValue = value ? value.trim() : '';
      if (this.fieldMapping[trimmedKey]) {
        normalized[this.fieldMapping[trimmedKey]] = trimmedValue;
      }
    }
    return normalized;
  }

  buildCompoundFilter(normalizedRecord) {
    const filters = [];
    for (const [attr, val] of Object.entries(normalizedRecord)) {
      if (val) {
        filters.push(this.service.buildFilter(attr, val));
      }
    }
    if (filters.length === 0) return null;
    if (filters.length === 1) return filters[0];
    return `(|${filters.join('')})`;
  }

  async processFile(filePath) {
    const records = await this._parseCSV(filePath);
    const results = [];

    await this.service.connect();
    try {
      for (const record of records) {
        const normalized = this.normalizeRecord(record);
        const filter = this.buildCompoundFilter(normalized);
        if (filter) {
          const found = await this.service.searchUser(filter);
          results.push({ input: record, matches: found });
        }
      }
    } finally {
      this.service.disconnect();
    }
    return results;
  }

  _parseCSV(filePath) {
    return new Promise((resolve, reject) => {
      const results = [];
      fs.createReadStream(filePath)
        .pipe(csv())
        .on('data', (row) => results.push(row))
        .on('end', () => resolve(results))
        .on('error', reject);
    });
  }
}

app.post('/api/v1/batch-lookup', upload.single('userfile'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });

  const ext = path.extname(req.file.originalname).toLowerCase();
  if (ext !== '.csv') {
    fs.unlinkSync(req.file.path);
    return res.status(400).json({ error: 'Only CSV files accepted' });
  }

  const ldapConfig = {
    url: LDAP_URL,
    baseDN: LDAP_BASE_DN,
    bindDN: LDAP_BIND_DN,
    bindPW: LDAP_BIND_PW
  };

  const service = new UserLookupService(ldapConfig);
  const processor = new BatchProcessor(service);

  try {
    const results = await processor.processFile(req.file.path);
    res.json({ success: true, results });
  } catch (err) {
    res.status(500).json({ error: 'Processing failed', detail: err.message });
  } finally {
    fs.unlinkSync(req.file.path);
  }
});

app.listen(3000, () => console.log('Batch lookup service on :3000'));

module.exports = { app, LDAPFieldEncoder, UserLookupService, BatchProcessor };
